  AwakerTalent_117311_TalentDesc_1 = {
    Text = [[
The first Command Card Pollux plays in a turn deals DMG+200% of his ATK, generates Shield +50% of his DEF, and +10 Aliemus.
After the battle, Pollux's Base DMG and the "Atonement by Pain" DMG effect are increased by 20% in exploration, and the "Atonement by Pain" DMG effect is doubled in Boss Battle.]]
  },
  AwakerTalent_117311_TalentName_1 = {
    Text = "Atonement by Pain"
  },
  AwakerTalent_120347_TalentDesc_1 = {
    Text = "When Murphy: Fauxborn is in the team, the Aequor Realm ascends to <Bold:Divine Realm: Aequor>.\nTentacle DMG is changed to 5% of the team's Max HP.\nTeam DMG Amplification +50% after exploration begins (Effect doubled if the team is entirely Aequor and Chaos Awakeners, though no additional starting Tentacles will be obtained).\nTentacle Gathering effect is removed.\n<Bold:Divine Realm: Tentacle Stance> features the following new effects:\n<Bold:Divine Realm: Tranquil Sea>: Immediately generate Shield equal to 25% Max HP, and Tentacles will no longer attack at turn end; 3 turns cooldown.\n<Bold:Divine Realm: Raging Waves>: Tentacle DMG × 125% for the turn; after dealing Active DMG, 1 Tentacle attacks; lose 1 Tentacle at turn end; 3 turns cooldown.\nRealm Mastery is counted as <Bold:Divine Realm: Aequor Mastery>:\nEach point provides: Tranquil Sea Stance's Shield Generation +0.025% Max HP. Raging Waves Stance's Tentacle DMG +0.025%. Effect doubled if the team is entirely Aequor and Chaos Awakeners."
  },
  AwakerTalent_120347_TalentName_1 = {
    Text = "Divine Realm's Order"
  },
  AwakerTalent_122481_TalentDesc_1 = {
    Text = [[
This talent is only effective in the "Astral Reign" stages.
This Awakener's CON, ATK, and DEF are increased by [Arg1]%, and they gain [Arg2] Keyflare upon their first Rouse.
Mouchette's Final DMG against "Dominator" enemies +[Arg5]%. All Awakeners' "Strike" Base DMG +[Arg3]%. After triggering Death Resistance, Mouchette gains [Arg4] Aliemus.]]
  },
