  },
  AwakerTalent_130920_TalentDesc_1 = {
    Text = [[
This talent is only effective in the "Astral Reign" stages.
This Awakener's CON, ATK, and DEF are increased by [Arg1]%, and they gain [Arg2] Keyflare upon their first Rouse.
"Vortex! Shell!" Base Fixed DMG +[Arg3]%.
Vortice removes the target's "Fortress" and "Temporary Fortress" effects before unleashing Exalt; if successfully removed, this Exalt's Crit. DMG +[Arg4]%.]]
  },
