  AwakerTalent_131854_TalentDesc_1 = {
    Text = ": When Saya is in the team, the \"Caro\" Realm is replaced with the \"Breeding·Caro\" Realm.\n: The automatic Crimson Furnace accumulation at turn start changes to 10% of HP lost, and the maximum accumulation changes to 50% of Max HP, with a 3-turn cooldown after use.\n: After exploration begins, the team's DMG Amplification +50%. If the team consists solely of Caro or Chaos Awakeners, the DMG Amplification gained from this effect is doubled, but no additional Tentacles are gained at the start of battle.\n: The Embryo Fusion Limit is increased from 100 to 200.\n: \"Embryo\" becomes \"Breeding·Embryo\": When Devoured, triggers the Devour effect 2 times, and can be used directly to provide 50 Aliemus to an Awakener. Direct use no longer grants Crit. Rate, and Embryos are no longer automatically converted to Crimson Furnace at turn end.\n: \"Scion of Purity\" becomes \"Breeding·Scion of Purity\": If there is no \"Breeding·Embryo\" in hand, it will be treated as a \"Breeding·Embryo\" to consume, triggering the Devour effect 3 times. Can be used directly to provide 75 Aliemus to an Awakener. Direct use no longer grants Crit. Rate, and Embryos are no longer automatically converted to Crimson Furnace at turn end.\n: Realm Mastery changes to \"Breeding·Caro Mastery.\" Each point of Realm Mastery increases the final DMG, Shield, Strength changes, Tentacle DMG, HP Healing, fixed Poison, and fixed Counter effects of Exalt used by Awakeners who consumed Embryo this turn by 0.03%. \n: If the team consists solely of Caro or Chaos Awakeners, the \"Breeding·Caro Mastery\" effect is doubled."
  },
  AwakerTalent_131854_TalentName_1 = {
    Text = "Breeding Caro"
  },
