  AwakerTalent_44845_TalentDesc_1 = {
    Text = [[
For every 1% Death Resistance Lily and her equipped WoD & Covenant have, the Base Shield of "Forbidden Swamp" and "Basic Defense" increases by 0.25%, and in Boss Battles, the accumulation and limit of Endure increase by 0.25%.
When Lily is in the team, gain 1 stack of Endure for each lost HP, with an Endure stack limit equal to Max HP.]]
