    Text = "Salvador's Furnace Healing benefits from the HP Recovery Boost."
  },
  AwakerTalent_46445_TalentName_1 = {
    Text = "Shepard of the Souls"
  },
  AwakerTalent_46446_TalentDesc_1 = {
    Text = [[
Ramona gains an additional 2.5 Keyflare Regen attribute. Each Affinity level additionally grants Ramona 0.5 Keyflare Regen attribute.
For each point of Keyflare Regen Level, increase the Base DMG of "Queen's Sword" by 1%, and after playing, gain 0.75 temporary Realm Mastery.]]
  },
  AwakerTalent_46446_TalentName_1 = {
    Text = "Silverheart Resonance"
  },
  AwakerTalent_46487_TalentDesc_1 = {
    Text = [[
Ramona: Timeworn obtains an additional 2.5 Keyflare Regen attribute. Each Affinity level additionally grants Ramona: Timeworn 0.5 Keyflare Regen attribute.
For each Keyflare Regen Level attribute, the loop effect of "Basic Strike" grants Ramona: Timeworn 0.2% Crit. Rate, and the loop effect of "Basic Defense" grants Ramona: Timeworn 0.2 Aliemus.]]
  },
  AwakerTalent_46487_TalentName_1 = {
    Text = "Silverheart Resonance"
  },
  AwakerTalent_49872_TalentDesc_1 = {
    Text = "For each 1 Realm Mastery Attributes Nautila possesses, the Counter DMG from \"Ready and Set\" increases by 0.25%."
  },
  AwakerTalent_49872_TalentName_1 = {
    Text = "Daily Maintenance"
  },
  AwakerTalent_49873_TalentDesc_1 = {
    Text = "For every 1% DMG Amplification attribute Nymphaea has, the Base Poison Effect caused by \"Knell of Death\" and \"Passage of the Ego\" increases by 0.5%."
  },
  AwakerTalent_49873_TalentName_1 = {Text = "Immerse"},
  AwakerTalent_51744_TalentDesc_1 = {
    Text = [[
At the start of the battle, place 1 "Obsession" into hand.
Miryam's "Basic Strike" enjoys 50% Tentacle DMG bonus.
For every 1% Crit. DMG provided by Miryam and her equipped Wheel of Destiny & Covenant, enhance her Exalt's STR Generation, Tentacle DMG, Aliemus, and Poison Application/Trigger effects by 0.2%.]]
  },
  AwakerTalent_51744_TalentName_1 = {
