  AwakerTalent_74118_TalentDesc_1 = {
    Text = [[
This talent is only effective in the "Astral Reign" stages.
This Awakener's CON, ATK, and DEF are increased by [Arg1]%, and they gain [Arg2] Keyflare upon their first Rouse.
Goliath's Base DMG is increased by [Arg3]%, and "Blade's Dominion" temporarily increases Goliath's Final DMG by [Arg4]%.
When there are 1/2/3 other "Lemurian" Awakeners in the team, all Awakeners' STR Generation is increased by 6%/15%/30%.]]
  },
