The Awakeners' CON, Attack, and DEF are increased by [Arg1] %, and they gain [Arg2] Keyflare upon their first Rouse.
When Tawil plays a card originally belonging to other Awakeners in the team, the corresponding Awakeners' Final DMG, Shield, and HP Recovery in this turn are increased by [Arg3] %, and this effect does not stack.]]
