  AwakerTalent_78618_TalentDesc_1 = {
    Text = "This talent is only effective in the \"Astral Reign\" stages.\nThis Awakener's CON, ATK, and DEF are increased by [Arg1]%, and they gain [Arg2] Keyflare upon their first Rouse.\nThe Base DMG of \"Atonement by Pain\" increase by [Arg3]％ of Pollux's ATK.\nFor every 50 stacks of \"Sin Mark,\" add 1 \"Sacred Heart\" to your hand.\nWhen \"Sin Mark\" reaches 100 stacks, pull 1 Pollux's Skill Card after \"Sacred Heart\" is Exhausted at 3rd play.\nWhen dealing DMG, the effect of \"Sin Mark\" is doubled against enemies of the \"Church of the Lightbearers\"."
  },
