  AwakerTalent_78620_TalentDesc_1 = {
    Text = [[
This talent is only effective in the "Astral Reign" stages.
This Awakener's CON, ATK, and DEF are increased by [Arg1]%, and they gain [Arg2] Keyflare upon their first Rouse.
At the start of battle, all enemies take [Arg3]% more Tentacle DMG. This effect doubles against "Aequor" enemies. The DMG dealt by "Lightning Retribution" to "Aequor" enemies increases by [Arg4]%.]]
  },
