  AwakerTalent_78624_TalentDesc_1 = {
    Text = "This talent is only effective in the \"Astral Reign\" stages.\nThis Awakener's CON, ATK, and DEF are increased by [Arg1]%, and they gain [Arg2] Keyflare upon their first Rouse.\nPlaying \"Onyx Plume\" will not add \"Arithmetica Harmony\". Corrosion inflicted with \"Cleansing Feathers\" is increased by [Arg3]% of Castor's ATK. Corrosion inflicted to enemies of the \"Church of the Lightbearers\" + [Arg4]％."
