When Clementine deals DMG to "Insectoid" enemies, she inflicts a Bleed effect equal to [Arg4]% of the DMG dealt. The first time each round Clementine provides a Shield or recovers HP, "Insectoid" enemies temporarily lose Strength equal to [Arg5]% of Clementine's DEF.]]
  },
